  'Cancel move': 'Anulează mutarea',
  'Cancel copy': 'Anulează copierea',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Mută conversația salvată completă, lista de verificare, atașamentele și fișierele. Sesiunile și datele de autentificare ale furnizorului rămân aici. Conversația de destinație folosește mediul de execuție implicit al acelui computer, fără mai mult acces decât are această conversație. Nimic nu rulează până când nu trimiți următorul mesaj acolo. Poți schimba modelul după ce se deschide. Această conversație rămâne aici, doar pentru citire, pentru recuperare.',
