    'Activează utilizarea computerului de către agenți pe acest computer',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Acordă agenților cu acces de scriere acces la desktopul acestui computer. Agenții cu acces doar pentru citire sunt excluși. Utilizatorul și agenții partajează desktopul și starea aplicațiilor.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Lasă Cua Driver necompletat pentru a-l detecta pe PATH-ul acestui computer sau în folderul său standard de instalare. Modificările se aplică rundelor noi ale agentului.',
  '1. Install on this computer': '1. Instalează pe acest computer',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Rulează programul oficial de instalare pe gazda runtime-ului, apoi reîmprospătează starea. Acesta descarcă și instalează CuaDriver; nu este necesar un cont Cua.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Sistemele Linux minimale au nevoie de libxi6 și at-spi2-core. GNOME are nevoie de utilitarul WinRects inclus cu Cua; consultă ghidul de instalare.',
  'Install and set up Cua Driver': 'Instalează și configurează Cua Driver',
  'Detect / check Cua Driver': 'Detectează / verifică Cua Driver',
  '2. Permissions & desktop access': '2. Permisiuni și acces la desktop',
  '3. Agent MCP, skills & hooks': '3. MCP, competențe și hook-uri pentru agent',
  '4. Computer History (optional preview)': '4. Istoricul computerului (previzualizare opțională)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Acordă CuaDriver permisiunile Accesibilitate și Înregistrare ecran pe macOS și acceptă repornirea acestuia. Testarea accesului la desktop afișează aplicațiile fără a le modifica. Comenzile daemonului afectează sesiunile active de utilizare a computerului.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Salvează comutatorul de utilizare a computerului pentru activarea automată a MCP dovo_cua în rundele noi cu acces de scriere. Nu este necesară înregistrarea manuală a MCP. Instalează pachetul oficial opțional de competențe; instalarea conectează agenții detectați pe acest computer.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Istoric criptat, doar cu metadate, activat opțional. Activarea poate reporni daemonul. Dezactivarea păstrează datele înregistrate; pauza oprește temporar înregistrarea. Versiunile neacceptate raportează o eroare. Datele rămân pe gazda runtime-ului; Vezi istoricul recent preia aici până la 20 de evenimente.',
  'Delete recorded Computer History?': 'Ștergi istoricul înregistrat al computerului?',
