    'Sugerează un prompt următor după un răspuns Claude sau Codex. Atinge sugestia pentru a o insera fără a o trimite. Pe desktop, apasă Tab pentru a o insera sau Escape pentru a o respinge. Fiecare sugestie face o solicitare suplimentară către model și consumă din plan.',
  'Scheduled worker capacity': 'Capacitate pentru lucrări programate',
  'Scheduled jobs wait at this threshold. One slot stays available for conversation work. Direct messages and needed children can exceed it. Running work is kept.':
    'Lucrările programate așteaptă când se atinge acest prag. Un loc rămâne disponibil pentru conversații. Mesajele directe și sarcinile copil necesare pot depăși limita. Lucrările în curs sunt păstrate.',
  'Continue interrupted turns after runtime restart':
    'Continuă turele întrerupte după repornirea runtime-ului',
