  'View tasks on this device': 'Vezi sarcinile de pe acest dispozitiv',
  'This computer connection changed. Choose where to create this work again.':
    'Conexiunea acestui computer s-a schimbat. Alege din nou unde să creezi această lucrare.',
  'Choose another computer': 'Alege alt computer',
  'Choose where this work should run.': 'Alege unde ar trebui să ruleze această lucrare.',
  'Shows connection details': 'Afișează detaliile conexiunii',
  'Reconnects. Touch and hold for details': 'Reconectează. Ține apăsat pentru detalii',
  'This phone is no longer paired with a computer below. It was removed on that computer, or the runtime was reset. Pair it again from Devices in Settings.':
    'Telefonul nu mai este asociat cu niciunul dintre computerele de mai jos. A fost eliminat de pe acel computer sau runtime-ul a fost resetat. Asociază-l din nou din Dispozitive în Setări.',
  'Connected using HTTP updates. Live streaming is reconnecting or unavailable. Reconnect to retry it.':
    'Conectat folosind actualizări HTTP. Transmiterea în timp real se reconectează sau nu este disponibilă. Reconectează-te pentru a încerca din nou.',
  'Saved work stays available. Reconnect a computer to send messages or run commands there.':
    'Lucrările salvate rămân disponibile. Reconectează un computer pentru a trimite mesaje sau a rula comenzi acolo.',
  '{value0} · {value1} saved actions': '{value0} · {value1} acțiuni salvate',
  'Thread: {value0}': 'Conversație: {value0}',
  'Computer access changed. This action may already have run.':
    'Accesul la computer s-a schimbat. Este posibil ca această acțiune să fi fost deja executată.',
  'Retry action': 'Reîncearcă acțiunea',
  'Retry this action?': 'Reîncerci această acțiune?',
  'Computer access changed. This action may already have run; retrying could repeat it. Check the computer before continuing.':
    'Accesul la computer s-a schimbat. Este posibil ca această acțiune să fi fost deja executată; reîncercarea ar putea s-o repete. Verifică computerul înainte de a continua.',
  'Discard action': 'Renunță la acțiune',
  'Discard this action?': 'Renunți la această acțiune?',
  'Unsent work will be removed from this phone. Actions already applied on the computer remain applied.':
    'Lucrarea netrimisă va fi eliminată de pe acest telefon. Acțiunile deja aplicate pe computer rămân aplicate.',
  'Retry saved actions': 'Reîncearcă acțiunile salvate',
  'Retry saved actions on {value0}?': 'Reîncerci acțiunile salvate pe {value0}?',
  'Access to this computer was renewed. Some saved actions may already have run and retrying could repeat them. Check the computer before continuing. Messages keep their original delivery identity.':
    'Accesul la acest computer a fost reînnoit. Este posibil ca unele acțiuni salvate să fi fost deja executate, iar reîncercarea le-ar putea repeta. Verifică computerul înainte de a continua. Mesajele își păstrează identitatea inițială de livrare.',
  'Discard saved actions': 'Renunță la acțiunile salvate',
  'Discard saved actions?': 'Renunți la acțiunile salvate?',
  'Actions already applied on the computer will remain applied. Unsent actions will be removed from this phone.':
    'Acțiunile deja aplicate pe computer vor rămâne aplicate. Acțiunile netrimise vor fi eliminate de pe acest telefon.',
  'Saved attachment': 'Atașament salvat',
  'Attach to the task’s current draft or discard the upload. Existing files remain unchanged.':
    'Atașează-l la ciorna curentă a sarcinii sau renunță la încărcare. Fișierele existente rămân neschimbate.',
  'Attach to current task draft': 'Atașează la ciorna curentă a sarcinii',
  'Attach saved file?': 'Atașezi fișierul salvat?',
  'This adds the saved file to the current draft of its original task. It does not modify a queued message.':
    'Aceasta adaugă fișierul salvat la ciorna curentă a sarcinii inițiale. Nu modifică un mesaj aflat în coadă.',
  Attach: 'Atașează',
  'Discard saved upload': 'Renunță la încărcarea salvată',
  'Discard saved upload?': 'Renunți la încărcarea salvată?',
  'This permanently abandons this upload. An attachment already saved in a message or draft is not removed.':
    'Această încărcare va fi abandonată definitiv. Un atașament deja salvat într-un mesaj sau într-o ciornă nu este eliminat.',
  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Asociază din nou',
  'Connection stages': 'Etapele conectării',
  'Start your computer': 'Pornește computerul',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Deschide Dovo pe computer și lasă-l pornit. În Setări → Dispozitive și runtime, autentifică-te și activează Dovo Connect. Autentifică-te în același cont pe telefon și alege Conectare. Pentru acces la internet nu ai nevoie de cod de asociere, VPN sau IP local.',
  'Direct internet connection': 'Conexiune directă la internet',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN conectează telefonul direct la computer. Conținutul tău este criptat integral. Activarea Dovo Connect permite folosirea unui releu de rezervă criptat dacă rețeaua blochează conexiunile directe. Releul transmite traficul criptat, dar nu poate citi conținutul.',
  'LAN / VPN connections': 'Conexiuni LAN / VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Asociază separat prin LAN / VPN pentru a prefera această conexiune când este disponibilă. Copiază adresa completă Wi-Fi, Tailscale, NetBird sau HTTPS afișată pe computer, inclusiv portul. localhost și 0.0.0.0 nu sunt adrese la care telefonul se poate conecta.',
  'Check your network': 'Verifică rețeaua',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Folosește aceeași rețea Wi-Fi sau conectează ambele dispozitive la VPN. Pentru conexiunile Wi-Fi, permite accesul Dovo la rețeaua locală din Configurări iPhone.',
