  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Rulează agentul fiecărei conversații noi, comenzile și terminalele sale într-un container Docker sau Podman local. Se montează doar copia de lucru și autentificarea agentului ales. Conversațiile în curs își păstrează setarea.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Fără acces la rețea, agentul nu poate ajunge la API-ul modelului său, decât dacă acel API rulează în sandbox. Instalările de pachete și cererile web eșuează și ele.',
